MinimaxHailuoVideoNode.schema:
IO.Schema(node_id='MinimaxHailuoVideoNode', display_name='MiniMax Hailuo Video', category='partner/video/MiniMax', description='Generates videos from prompt, with optional start frame using the new MiniMax Hailuo-02 model.', inputs=[IO.String.Input('prompt_text', multiline=True, default='', tooltip='Text prompt to guide the video generation.'), IO.Int.Input('seed', default=0, min=0, max=18446744073709551615, step=1, control_after_generate=True, tooltip='The random seed used for creating the noise.', optional=True), IO.Image.Input('first_frame_image', tooltip='Optional image to use as the first frame to generate a video.', optional=True), IO.Boolean.Input('prompt_optimizer', default=True, tooltip='Optimize prompt to improve generation quality when needed.', optional=True), IO.Combo.Input('duration', options=[6, 10], default=6, tooltip='The length of the output video in seconds.', optional=True), IO.Combo.Input('resolution', options=['768P', '1080P'], default='768P', tooltip='The dimensions of the video display. 1080p is 1920x1080, 768p is 1366x768.', optional=True)], outputs=[IO.Video.Output()], hidden=[IO.Hidden.auth_token_sim_org, IO.Hidden.api_key_sim_org, IO.Hidden.unique_id], is_api_node=True, price_badge=IO.PriceBadge(depends_on=IO.PriceBadgeDepends(widgets=['resolution', 'duration']), expr='
                (
                  $prices := {
                    "768p": {"6": 0.28, "10": 0.56},
                    "1080p": {"6": 0.49}
                  };
                  $resPrices := $lookup($prices, $lowercase(widgets.resolution));
                  $price := $lookup($resPrices, $string(widgets.duration));
                  {"type":"usd","usd": $price ? $price : 0.43}
                )
                '))
